namespace fusion {
inline void elementwise(const float* gate, const float* up, float* out, size_t first, size_t last) {
    for (size_t i = first; i < last; ++i) {
        float g = gate[i] / (1.0f + std::exp(-gate[i]));
        out[i] = g * up[i];
    }
}
template<bool Fused> void run(backend::CpuBackend& cpu, const uint8_t* gate_w,
    const uint8_t* up_w, const float* x, float* gate, float* up, float* out,
    size_t nin, size_t rows) {
    const size_t nt = size_t(cpu.threads_available());
    const size_t chunk = (rows + nt - 1) / nt;
    const size_t blocks = nin / gguf::Q8_0_BLOCK;
    cpu.run_parallel([&](int w) {
        const size_t first = size_t(w) * chunk;
        const size_t last = std::min(rows, first + chunk);
        for (size_t i = first; i < last; ++i)
            gate[i] = cpu.dot_row_impl(gate_w + i * blocks * gguf::Q8_0_TYPESIZE, x, blocks);
        for (size_t i = first; i < last; ++i)
            up[i] = cpu.dot_row_impl(up_w + i * blocks * gguf::Q8_0_TYPESIZE, x, blocks);
        if constexpr (Fused) elementwise(gate, up, out, first, last);
    });
    if constexpr (!Fused) elementwise(gate, up, out, 0, rows);
}
}

#include "fusion.hpp"
#include <chrono>
#include <iomanip>
#include <iostream>
using Clock = std::chrono::steady_clock;
struct Fixture {
    size_t nin, rows;
    std::vector<uint8_t> a,b;
    std::vector<float> x,gate,up,out;
    Fixture(size_t n,size_t m):nin(n),rows(m),a(m*(n/32)*34),b(a.size()),x(n),gate(m),up(m),out(m) {
        uint32_t seed=12345;
        for (auto* v : {&a,&b}) for(size_t k=0;k<v->size()/34;++k) {
            uint16_t h=uint16_t(0x1800+k%0x400);
            (*v)[k*34]=uint8_t(h); (*v)[k*34+1]=uint8_t(h>>8);
            for(size_t j=0;j<32;++j){seed=seed*1664525u+1013904223u;(*v)[k*34+2+j]=uint8_t(seed>>24);}
        }
        for(size_t j=0;j<n;++j)x[j]=float(int(j%257)-128)/129.0f;
    }
    template<bool F> void run(backend::CpuBackend& cpu) {
        fusion::run<F>(cpu,a.data(),b.data(),x.data(),gate.data(),up.data(),out.data(),nin,rows);
    }
};
int main() {
    try {
        backend::CpuBackend cpu; cpu.set_threads(6);
        if (!cpu.avx2_ || !cpu.f16c_) throw std::runtime_error("AVX2/FMA/F16C required");
        struct Shape {const char* name;size_t nin,rows;int iterations;};
        const Shape shapes[]={{"small_gate_up_swiglu",1024,3072,512},{"large_gate_up_swiglu",4096,12288,64}};
        std::cout<<std::setprecision(15);
        for(const auto& shape:shapes) {
            Fixture f(shape.nin,shape.rows);
            f.run<false>(cpu); const auto gate=f.gate,up=f.up,out=f.out;
            auto check=[&](){
                if(std::memcmp(gate.data(),f.gate.data(),shape.rows*4)||std::memcmp(up.data(),f.up.data(),shape.rows*4)||std::memcmp(out.data(),f.out.data(),shape.rows*4))
                    throw std::runtime_error("exact gate/up/SwiGLU mismatch");
            };
            f.run<true>(cpu);check();
            std::cout<<"{\"kind\":\"shape\",\"name\":\""<<shape.name<<"\",\"nin\":"<<shape.nin<<",\"rows\":"<<shape.rows<<",\"iterations\":"<<shape.iterations<<"}\n"<<std::flush;
            for(int pair=-1;pair<9;++pair) for(int order=0;order<2;++order) {
                bool fused=(pair>=0&&pair%2)?order==0:order==1;
                const auto start=Clock::now();
                for(int i=0;i<shape.iterations;++i) {if(fused) f.run<true>(cpu);else f.run<false>(cpu);}
                double ms=std::chrono::duration<double,std::milli>(Clock::now()-start).count();check();
                std::cout<<"{\"kind\":\"sample\",\"name\":\""<<shape.name<<"\",\"pair\":"<<pair<<",\"arm\":\""<<(fused?"fused":"serial")<<"\",\"ms\":"<<ms<<"}\n"<<std::flush;
            }
        }
    }catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}
}

