static std::atomic<unsigned>* row_hits;
static size_t witness_rows;
static std::thread::id caller;
static std::atomic<size_t> other_rows{0};
static std::atomic<bool> witness_bad{false};
static bool standard_fp() {
    return std::fegetround() == FE_TONEAREST && (_mm_getcsr() & (0x6000u | 0x8040u)) == 0;
