#pragma once
#include "cpu_access.hpp"
namespace witnessed_fusion {
inline void elementwise(const float* gate, const float* up, float* out, size_t first, size_t last) {
    for (size_t i = first; i < last; ++i) {
        float g = gate[i] / (1.0f + std::exp(-gate[i]));
        out[i] = g * up[i];
        record_row(i);
    }
}
template<bool Fused> void run(backend::CpuBackend& cpu, const uint8_t* gate_w,
    const uint8_t* up_w, const float* x, float* gate, float* up, float* out,
    size_t nin, size_t rows) {
    const size_t nt = size_t(cpu.threads_available());
    const size_t chunk = (rows + nt - 1) / nt;
    const size_t blocks = nin / gguf::Q8_0_BLOCK;
    cpu.run_parallel([&](int w) {
        const size_t first = size_t(w) * chunk;
        const size_t last = std::min(rows, first + chunk);
        for (size_t i = first; i < last; ++i)
            gate[i] = cpu.dot_row_impl(gate_w + i * blocks * gguf::Q8_0_TYPESIZE, x, blocks);
        for (size_t i = first; i < last; ++i)
            up[i] = cpu.dot_row_impl(up_w + i * blocks * gguf::Q8_0_TYPESIZE, x, blocks);
        if constexpr (Fused) elementwise(gate, up, out, first, last);
    });
    if constexpr (!Fused) elementwise(gate, up, out, 0, rows);
}
}

